get_epoch_us() {
  local t=$EPOCHREALTIME
  local sec=${t%.*}
  local usec=${t#*.}
  usec=$((10#$usec))
  EPOCH_US=$((sec*1000000 + usec))
}

tput civis 2>/dev/null
clear

get_epoch_us
START_US=$EPOCH_US
i=0
for frame in "${FRAMES[@]}"; do
  printf '\033[H%s' "$frame"
  i=$((i+1))
  target=$((START_US + i*FRAME_US))
  get_epoch_us
  diff=$((target - EPOCH_US))
  if [ "$diff" -gt 0 ]; then
    sec=$((diff/1000000))
    usec=$((diff%1000000))
    printf -v st "%d.%06d" "$sec" "$usec"
    sleep "$st"
  fi
done

wait "$AUDIO_PID" 2>/dev/null
